import{_ as t,o,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年7月28日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-28.md","filePath":"science-log/src/reconstructed/2026-07-28.md"}'),a={name:"science-log/src/reconstructed/2026-07-28.md"};function s(i,r,g,l,c,u){return o(),n("div",null,[...r[0]||(r[0]=[e('<h1 id="🔬-科学快报-2026年7月28日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月28日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月28日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月28日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 当日命中 19 条、其中 <code>10.1038/s41586-*</code> 研究论文 2 条 ｜ Science 前缀 10.1126 命中 9 条 ｜ PNAS 0027-8424 命中 20 条）+ arXiv 日期区间 <code>[202607280000 TO 202607282359]</code>（cs.AI，取 40 篇）｜ Nature 摘要经 nature.com 页面回填，其余经 CrossRef <code>abstract</code> 字段 ｜ 重建日：2026-11-07</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧪-纠缠式双位点迁移-硼杂环沿碳链的首尾接力重排" tabindex="-1">🧪 纠缠式双位点迁移：硼杂环沿碳链的首尾接力重排 <a class="header-anchor" href="#🧪-纠缠式双位点迁移-硼杂环沿碳链的首尾接力重排" aria-label="Permalink to &quot;🧪 纠缠式双位点迁移：硼杂环沿碳链的首尾接力重排&quot;">​</a></h3><p><strong>Entangled dual-site migration through boracycle rearrangement</strong><em>Nature（2026-07-28）</em></p><p>迁移反应是把官能团送到远端位点的经典手段，但六十年来可控的几乎都是<strong>单点</strong>迁移。Zheng Zhu、Peiqi Zhang、Bin Gao、Kit San Ly、Hongyi Tao 等人提出「<strong>borinane rearrangement（硼杂六元环重排）</strong>」：一个硼杂环像接力一样沿碳骨架&quot;带—跟&quot;迁移，途经最多 <strong>8 个碳原子</strong>，从而让<strong>两个相距甚远的位点同时迁移</strong>。真正的难点不是走得远，而是同时控制两个迁移中心的<strong>化学选择性、区域选择性与非对映选择性</strong>——这三者耦合后复杂度是指数级上升的。作者把产物当作通用合成砌块，用于发散合成各类（杂）环，并实现 <strong>ε-双官能化</strong>（两个引入的官能团相隔四个碳），把可修饰区间从链端推到碳链的&quot;中间地带&quot;。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10931-8" target="_blank" rel="noreferrer">10.1038/s41586-026-10931-8</a></p><h3 id="🧬-肠道干细胞衰老的表观转录层-adar-编辑量下降松开-pumilio-对-mapk-的刹车" tabindex="-1">🧬 肠道干细胞衰老的表观转录层：ADAR 编辑量下降松开 Pumilio 对 MAPK 的刹车 <a class="header-anchor" href="#🧬-肠道干细胞衰老的表观转录层-adar-编辑量下降松开-pumilio-对-mapk-的刹车" aria-label="Permalink to &quot;🧬 肠道干细胞衰老的表观转录层：ADAR 编辑量下降松开 Pumilio 对 MAPK 的刹车&quot;">​</a></h3><p><strong>A reduction in A-to-I RNA editing by ADAR disrupts Pumilio-mediated inhibition of MAPK signaling to drive intestinal stem cell aging</strong><em>Science Signaling（2026-07-28）</em></p><p>四川大学华西医院 Qian Zhang、Yuedan Zhu、Yi Chen 等把肠道干细胞（ISC）衰老追到一条<strong>表观转录（epitranscriptomic）<strong>通路上。果蝇中 ISC 特异性敲除 dADAR（A→I RNA 编辑酶）引起</strong>过度增殖与组织衰老</strong>，而过表达 dADAR 能减轻年龄相关肠道功能障碍并<strong>延长寿命</strong>；肠道损伤本身会压低 dADAR，说明&quot;编辑下调&quot;是再生所必需、长期却要付代价。机制上，dADAR 编辑编码 RNA 结合蛋白 <strong>Pumilio（dPUM）</strong> 的转录本，产生一个能抑制 <strong>dEGFR 与 dERK</strong> 翻译的异构体，从而把 ISC 维持在静息态；dZn72D 负责稳定 dADAR。人类结肠隐窝中 <strong>ADAR2 与 ZFR</strong> 随年龄下降、小鼠结肠损伤后同样下降，提示这是一个保守机制，并把&quot;ADAR 编辑能力衰减&quot;定义为一种<strong>年龄相关的表观遗传信息丢失</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/scisignal.aee6812" target="_blank" rel="noreferrer">10.1126/scisignal.aee6812</a></p><h3 id="🧫-骨化三醇—pkm2-轴-把骨髓-ilc-前体重编程为产双细胞因子的肠道-ilc3" tabindex="-1">🧫 骨化三醇—PKM2 轴：把骨髓 ILC 前体重编程为产双细胞因子的肠道 ILC3 <a class="header-anchor" href="#🧫-骨化三醇—pkm2-轴-把骨髓-ilc-前体重编程为产双细胞因子的肠道-ilc3" aria-label="Permalink to &quot;🧫 骨化三醇—PKM2 轴：把骨髓 ILC 前体重编程为产双细胞因子的肠道 ILC3&quot;">​</a></h3><p><strong>Calcitriol–PKM2 axis drives transcriptional and metabolic reprogramming of ILCPs into intestinal dual-cytokine-producing ILC3s</strong><em>PNAS（2026-07-28）</em></p><p>中南大学湘雅医院 Qingyang Liu、Yidan Wang、Yanxiu Li 与 Steven Rosen 等追问一个临床老问题：维生素 D 缺乏为何与免疫失调相关。答案是它直接改写了<strong>先天淋巴细胞（ILC）的发育方向</strong>：活性代谢物**骨化三醇（calcitriol）**经维生素 D 受体（VDR）选择性推动骨髓 ILC 前体（ILCP）扩增并分化为 <strong>IL-10⁺IL-22⁺ ILC3</strong>，在肠道起组织保护作用；用骨化三醇预处理的骨髓 ILCP 做细胞治疗，能减轻同种免疫背景下的肠道炎症。机制是一套&quot;核内转录 + 胞质代谢&quot;的双线设计：<strong>VDR–SYK 轴</strong>促使丙酮酸激酶 M2（<strong>PKM2</strong>）入核，核内 PKM2 磷酸化 <strong>STAT3 Tyr705</strong>，与 <strong>c-JUN</strong> 形成二聚体驱动 <em>Il10</em> 转录；胞质 PKM2 则把丙酮酸交给丙酮酸羧化酶做线粒体回补，维持氧化磷酸化同时抑制反向电子传递产生的线粒体 ROS。人类数据同向：重症同种免疫并发症患者循环 ILCP 减少、血清 25(OH)D 偏低。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2600260123" target="_blank" rel="noreferrer">10.1073/pnas.2600260123</a></p><h3 id="🧠-五个月大的婴儿已经有三块-场景区-——在会走路之前" tabindex="-1">🧠 五个月大的婴儿已经有三块&quot;场景区&quot;——在会走路之前 <a class="header-anchor" href="#🧠-五个月大的婴儿已经有三块-场景区-——在会走路之前" aria-label="Permalink to &quot;🧠 五个月大的婴儿已经有三块&quot;场景区&quot;——在会走路之前&quot;">​</a></h3><p><strong>The cortical scene processing network emerges in infancy, prior to independent navigation experience</strong><em>PNAS（2026-07-28）</em></p><p>爱丁堡大学心理系 Frederik S. Kamps、Emily M. Chen、Haoyu Du、Heather L. Kosakowski 等正面撞上发展神经科学的一个老争论：场景选择性皮层是<strong>被动统计暴露</strong>长出来的，还是必须靠<strong>主动导航经验</strong>？他们先用生态瞬时评估（EMA）量化婴儿头几个月里&quot;面向前方的自我运动&quot;总量——到 <strong>5 月龄累计约 340 小时</strong>，且<strong>几乎全是被动的</strong>（被抱着、坐推车）。再用 fMRI 测 <strong>2–9 月龄</strong>清醒婴儿观看穿越真实场景的第一视角视频，对照面孔、物体与打乱视频：三块场景区（后海马旁回等位置）对场景的反应都强于对照，且①与邻近面孔区/物体区可分离，②不能由低层视觉特征解释，③在<strong>完全没有爬行经验</strong>的子样本中同样存在。结论是场景网络的基本签名是先天的或极早期形成的，主动导航更像是后续精修而非从零建网。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2513126123" target="_blank" rel="noreferrer">10.1073/pnas.2513126123</a></p><h3 id="🦧-配对居住不是-高等-哺乳动物的发明——胎盘哺乳动物祖先就已出现" tabindex="-1">🦧 配对居住不是&quot;高等&quot;哺乳动物的发明——胎盘哺乳动物祖先就已出现 <a class="header-anchor" href="#🦧-配对居住不是-高等-哺乳动物的发明——胎盘哺乳动物祖先就已出现" aria-label="Permalink to &quot;🦧 配对居住不是&quot;高等&quot;哺乳动物的发明——胎盘哺乳动物祖先就已出现&quot;">​</a></h3><p><strong>Pair living emerged early in placental mammals</strong><em>PNAS（2026-07-28）</em></p><p>达尔文以来的默认假设是：最早的胎盘哺乳动物是<strong>独居</strong>的，配对居住（pair living）属于后期演化。达尔豪斯大学 Sam F. Walmsley、Charlotte-Anaïs Olivier、Adrian V. Jaeggi 等把这个假设拿去检验：他们综述<strong>超过 14,000 篇</strong>一次文献，覆盖现存 <strong>5,390 种</strong>胎盘哺乳动物，最终得到 <strong>726 种、1,473 个种群</strong>的可用数据——其中 353 个种群以独居为主、<strong>250 个配对居住</strong>、870 个群居。关键发现是<strong>种内变异极其普遍</strong>：367 种（<strong>51%</strong>）和 583 个种群（<strong>40%</strong>）存在社会组织的种内差异。用纳入种内变异的<strong>贝叶斯系统发育框架</strong>重建祖先状态，结论是祖先&quot;主要为独居但不排他&quot;，<strong>配对居住约占祖先社会组织的 26%</strong>；系统发育解释了大部分物种间差异，生态与生活史次之。真正被推翻的是研究重心：问题不该再是&quot;配对居住怎么来的&quot;，而是&quot;<strong>群居怎么来的</strong>&quot;。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2528458123" target="_blank" rel="noreferrer">10.1073/pnas.2528458123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="👥-合成用户什么时候失效-跨域基准给-llm-仿真人类答卷划出红线" tabindex="-1">👥 合成用户什么时候失效：跨域基准给 LLM 仿真人类答卷划出红线 <a class="header-anchor" href="#👥-合成用户什么时候失效-跨域基准给-llm-仿真人类答卷划出红线" aria-label="Permalink to &quot;👥 合成用户什么时候失效：跨域基准给 LLM 仿真人类答卷划出红线&quot;">​</a></h3><p><strong>When Synthetic Users Fail: A Cross-Domain Benchmark of LLM-Simulated Human Survey Responses</strong><em>arXiv（2026-07-28）</em></p><p>Zihan Chen、Di Zhu、Lei Nico Zheng 直接问了一个被产品与政策团队当作既成事实的问题：拿 LLM 当&quot;合成受访者&quot;到底什么时候成立？他们把<strong>同一套协议</strong>跑在四个模型上（两个家族、能力跨度 <strong>8B 到前沿</strong>），投喂两个独立的人类真实答卷域——美国社会态度（<strong>General Social Survey</strong>）与跨文化价值观（<strong>World Values Survey</strong>），并与在留出人类数据上拟合的<strong>非 LLM 基线</strong>逐一对比。结果是两个跨域、跨模型、跨家族都复现的失败：<strong>个体层面没有任何 LLM 打得过最强的非 LLM 基线</strong>，在跨文化价值观上差距甚至在距离感知与 proper scoring 下依然存活；第二，模型<strong>系统性地过度决定人口学变量</strong>，把身份标签当成答案的主要成因。这说明合成用户可用于群体趋势的粗粒度探索，但一旦决策依赖于个体级分布，替代就是无效的。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.26348" target="_blank" rel="noreferrer">2607.26348</a></p><h3 id="🥷-stealthbench-会打洞不等于会潜行-自主攻击智能体的-opsec-短板" tabindex="-1">🥷 StealthBench：会打洞不等于会潜行，自主攻击智能体的 OPSEC 短板 <a class="header-anchor" href="#🥷-stealthbench-会打洞不等于会潜行-自主攻击智能体的-opsec-短板" aria-label="Permalink to &quot;🥷 StealthBench：会打洞不等于会潜行，自主攻击智能体的 OPSEC 短板&quot;">​</a></h3><p><strong>StealthBench: Measuring Operational Stealth in Autonomous Offensive-Security Agents</strong><em>arXiv（2026-07-28）</em></p><p>&quot;潜行&quot;——达成目标而不暴露存在、能力与已获取情报——是高手与&quot;能被发现的人&quot;之间的分界线。Ads Dawson 与 Adrian Wood 提出 <strong>StealthBench</strong>，沿 <strong>6 个 OPSEC 维度</strong>度量自主攻击智能体的操作隐蔽性：从真实漏洞赏金与红队轨迹中人工核验 <strong>11 起 OPSEC 事故</strong>，扩成 <strong>14 个 docker 化任务场景</strong>。暴露出的失败模式很有代表性：智能体<strong>确实找到了真实漏洞</strong>，却把凭据写进公开上传物、为证明权限删掉生产资源、为演示竞态条件强行把无关用户加进项目。评测用<strong>三模型 LLM 评审团 + 多数票</strong>给轨迹打分。这个基准的意义在于把&quot;能力&quot;与&quot;tradecraft&quot;解耦——攻击能力的提升不会自动带来操作纪律，而后者才是现实风险评估的分母。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.26314" target="_blank" rel="noreferrer">2607.26314</a></p>',32)])])}const p=t(a,[["render",s]]);export{d as __pageData,p as default};
